import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong(), k = nextLong();
        long[] buckets = new long[101];
        for (long i = 0; i < n; i++) buckets[(int) nextLong()]++;
        // Rank of a score = 1 + players with a strictly higher score; score 0 is never promoted.
        long higher = 0, answer = 0;
        for (int score = 100; score >= 1; score--) {
            if (higher + 1 <= k) answer += buckets[score];
            higher += buckets[score];
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := nextInt(), nextInt()
	var buckets [101]int64
	for i := int64(0); i < n; i++ {
		buckets[nextInt()]++
	}
	// Rank of a score = 1 + players with a strictly higher score; score 0 is never promoted.
	higher, answer := int64(0), int64(0)
	for score := 100; score >= 1; score-- {
		if higher+1 <= k {
			answer += buckets[score]
		}
		higher += buckets[score]
	}
	fmt.Println(answer)
}
